  delete c._relative;
  if (Array.isArray(c.properties)) c.properties = c.properties.map(resolve);
  return c;
};
const std = {};
for (const [k, v] of Object.entries(FIXTURE.actual.standardObjectProperties)) std[k] = { properties: v.results.map(resolve), readError: null };
