// ─────────────────────────────────────────────────────────────────────────────
// Load Expected Template
// Source order: EXPECTED_SCHEMA_TEMPLATE_URL (fetched as text, parsed here),
// then EXPECTED_SCHEMA_TEMPLATE_JSON (parsed in Config). Full validation runs in
// the analysis node; this node only extracts the standard objects to read.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const STD = ['contacts', 'companies', 'deals', 'tickets', 'products', 'line_items', 'quotes'];
const errors = [];
let raw = null; let source = 'none';
if (cfg.templateUrlSet) {
  source = 'url';
  let r = null;
  try { r = $('HTTP: Fetch Expected Template').isExecuted ? $('HTTP: Fetch Expected Template').first().json : null; } catch (e) { r = null; }
  if (!r) errors.push('Template URL fetch returned no response.');
  else if (r.error) errors.push(`Template URL fetch failed: ${String(r.error.message || r.error).slice(0, 200)}`);
  else {
    const text = typeof r.data === 'string' ? r.data : JSON.stringify(r.data ?? r);
    try { raw = JSON.parse(text); } catch (e) { errors.push('Template URL did not return valid JSON.'); }
  }
} else if (cfg.templateInline) {
  source = 'env';
  if (cfg.templateInline.__invalid) errors.push('EXPECTED_SCHEMA_TEMPLATE_JSON is not valid JSON.');
  else raw = cfg.templateInline;
} else {
  errors.push('No expected template configured. Set EXPECTED_SCHEMA_TEMPLATE_URL or EXPECTED_SCHEMA_TEMPLATE_JSON.');
}
if (!errors.length && (!raw || typeof raw !== 'object' || Array.isArray(raw))) errors.push('Expected template is not a JSON object.');
const standardObjects = (!errors.length && raw.standardObjects && typeof raw.standardObjects === 'object')
  ? [...new Set(Object.keys(raw.standardObjects).map((k) => k.trim().toLowerCase()))].filter((k) => STD.includes(k)) : [];
return [{ json: { template: raw, templateSource: source, templateErrors: errors, valid: errors.length === 0, standardObjects } }];

// ─────────────────────────────────────────────────────────────────────────────
// Assemble Schema Context (live)
// Joins the template with the custom object schemas and the standard object
// property lists. A failed read becomes a read error, never an empty schema:
// an unreadable object must not look like a deleted one.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const L = $('Load Expected Template').first().json;
const bad = (j) => !j || j.error || j.status === 'error';
const msg = (j) => String(j?.error?.message || j?.message || j?.error || 'no response').slice(0, 200);
const readErrors = [];
let sch = null;
try { sch = $('HubSpot: Get Custom Object Schemas').first().json; } catch (e) { sch = null; }
let customObjects = null;
if (bad(sch)) readErrors.push({ scope: 'custom_objects', message: `Custom object schema read failed: ${msg(sch)}` });
else customObjects = Array.isArray(sch.results) ? sch.results : [];
let resp = [];
try { resp = $('HubSpot: Get Standard Object Properties').isExecuted ? $('HubSpot: Get Standard Object Properties').all() : []; } catch (e) { resp = []; }
const standardObjects = {};
L.standardObjects.forEach((o, i) => {
  const j = resp[i]?.json;
  standardObjects[o] = bad(j) ? { properties: null, readError: msg(j) } : { properties: Array.isArray(j.results) ? j.results : [], readError: null };
});
return [{ json: {
  source: 'hubspot', portalId: cfg.portalId, template: L.template, templateSource: L.templateSource, templateErrors: L.templateErrors,
  actual: { customObjects, standardObjects }, readErrors,
} }];

// ─────────────────────────────────────────────────────────────────────────────
// Schema Drift Analysis
// Compares actual HubSpot custom object schemas and standard object properties
// with the expected master template. Every finding has a stable key, a rule, a
// severity (critical / warning / info) and expected vs actual values.
// Reads, never writes, workflow memory: state is recorded after delivery.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const ctx = $input.first().json;
const now = Date.now();
const SEV = { ignore: 0, info: 1, warning: 2, critical: 3 };
const DEFAULT_SEV = {
  object_missing: 'critical', object_archived: 'critical', object_unmanaged: 'warning', object_label_changed: 'info',
  primary_display_changed: 'warning', required_flag_removed: 'critical', required_flag_added: 'warning',
  property_missing: 'critical', property_archived: 'critical', mass_property_loss: 'critical',
  property_type_changed: 'critical', property_field_type_changed: 'warning',
  property_option_removed: 'critical', property_option_hidden: 'warning', property_option_added: 'info', property_option_added_locked: 'warning',
  property_unique_changed: 'warning', property_label_changed: 'info',
  property_unmanaged: 'info', property_unmanaged_locked: 'warning', unmanaged_property_volume: 'warning',
  association_missing: 'critical', association_unmanaged: 'info', object_not_readable: 'warning',
};
const overrides = cfg.severityOverrides && typeof cfg.severityOverrides === 'object' ? cfg.severityOverrides : {};
const sevOf = (rule) => { const o = String(overrides[rule] ?? '').trim().toLowerCase(); return SEV[o] !== undefined ? o : DEFAULT_SEV[rule]; };
const STD = { contacts: '0-1', companies: '0-2', deals: '0-3', tickets: '0-5', products: '0-7', line_items: '0-8', quotes: '0-14' };
const STD_ALIAS = { contact: 'contacts', company: 'companies', deal: 'deals', ticket: 'tickets', product: 'products', line_item: 'line_items', quote: 'quotes' };
const STD_LABEL = { contacts: 'Contacts', companies: 'Companies', deals: 'Deals', tickets: 'Tickets', products: 'Products', line_items: 'Line items', quotes: 'Quotes' };
const ID_TO_STD = Object.fromEntries(Object.entries(STD).map(([k, v]) => [v, k]));
const TYPES = ['string', 'number', 'date', 'datetime', 'enumeration', 'bool', 'phone_number', 'object_coordinates', 'json'];
const TYPE_ALIAS = { boolean: 'bool', integer: 'number', decimal: 'number', enum: 'enumeration', phone: 'phone_number' };
const norm = (v) => String(v ?? '').trim().toLowerCase();
const normType = (t) => { const x = norm(t); return TYPE_ALIAS[x] || x; };
const glob = (p) => new RegExp(`^${String(p).replace(/[.+?^${}()|[\]\\]/g, '\\$&').replace(/\*/g, '.*')}$`, 'i');
const ignoreProps = (cfg.ignorePropertyPatterns || []).map(glob);
const ignoreObjects = (cfg.ignoreObjects || []).map(glob);
const isIgnoredProp = (n) => ignoreProps.some((r) => r.test(n));
const isIgnoredObj = (...names) => names.filter(Boolean).some((n) => ignoreObjects.some((r) => r.test(n)));

// ── Memory (read only) ───────────────────────────────────────────────────────
const persist = !cfg.sandboxMode && !['manual', 'test'].includes(cfg.executionMode);
const mem = persist ? ($getWorkflowStaticData('global').schemaDrift || {}) : {};
const prev = mem.findings && typeof mem.findings === 'object' ? mem.findings : {};

const base = { generatedAt: new Date(now).toISOString(), portalId: ctx.portalId || '', source: ctx.source, templateSource: ctx.templateSource, persist };

// ── Template validation ──────────────────────────────────────────────────────
const T = ctx.template;
const templateErrors = [...(ctx.templateErrors || [])];
const templateWarnings = [];
if (!templateErrors.length) {
  if (!T || typeof T !== 'object' || Array.isArray(T)) templateErrors.push('Expected template is not a JSON object.');
  else if (!T.customObjects && !T.standardObjects) templateErrors.push('Expected template has neither customObjects nor standardObjects.');
  else for (const k of ['customObjects', 'standardObjects']) if (T[k] !== undefined && (typeof T[k] !== 'object' || Array.isArray(T[k]))) templateErrors.push(`Template ${k} must be an object keyed by object name.`);
}
const failure = (kind, messages) => [{ json: { ...base, status: 'error', auditError: { kind, messages }, templateVersion: T?.templateVersion || null, templateWarnings, objects: [], findings: [], resolved: [],
  counts: { critical: 0, warning: 0, info: 0, total: 0, alertable: 0, new: 0, persisting: 0, resolved: 0, objectsAudited: 0 },
  alert: { needed: cfg.alertOnAuditFailure, reason: 'audit_failure' }, carryOver: Object.keys(prev), notes: [] } }];
if (templateErrors.length) return failure('template', templateErrors);
if (T.customObjects && Object.keys(T.customObjects).length && !Array.isArray(ctx.actual?.customObjects)) {
  return failure('hubspot_read', (ctx.readErrors || []).map((e) => e.message).concat(ctx.readErrors?.length ? [] : ['Custom object schemas were not returned.']));
}

// ── Normalise template entries ───────────────────────────────────────────────
function normTemplate(key, def, isStd) {
  const d = def && typeof def === 'object' ? def : {};
  const P = d.properties && typeof d.properties === 'object' ? d.properties : {};
  const entries = Array.isArray(P) ? P.map((p) => [p?.name, p]) : Object.entries(P);
  const required = new Set((Array.isArray(d.requiredProperties) ? d.requiredProperties : []).map(norm).filter(Boolean));
  const properties = {};
  for (const [n0, p0] of entries) {
    const name = norm(n0); if (!name) continue;
    const p = p0 && typeof p0 === 'object' ? p0 : {};
    let type = p.type !== undefined ? normType(p.type) : null;
    if (type && !TYPES.includes(type)) { templateWarnings.push(`${key}.${name}: unknown type "${p.type}" ignored`); type = null; }
    if (p.required === true && !isStd) required.add(name);
    properties[name] = {
      type, fieldType: p.fieldType ? norm(p.fieldType) : null, label: p.label ?? null,
      options: Array.isArray(p.options) ? p.options.map((o) => norm(o && typeof o === 'object' ? o.value : o)).filter(Boolean) : null,
      allowExtraOptions: p.allowExtraOptions !== false, hasUniqueValue: typeof p.hasUniqueValue === 'boolean' ? p.hasUniqueValue : null,
    };
  }
  if (isStd && d.requiredProperties) templateWarnings.push(`${key}: requiredProperties is ignored for standard objects (HubSpot has no object-level required flag for them)`);
  return {
    key, isStd, labels: d.labels && typeof d.labels === 'object' ? d.labels : null,
    primaryDisplayProperty: !isStd && d.primaryDisplayProperty ? norm(d.primaryDisplayProperty) : null,
    required: [...required], requiredDeclared: !isStd && (Array.isArray(d.requiredProperties) || entries.some(([, p]) => p && p.required !== undefined)),
    properties, allowUnmanaged: d.allowUnmanagedProperties !== false,
    reportUnmanaged: isStd ? d.allowUnmanagedProperties !== undefined : true,
    associations: !isStd && Array.isArray(d.associations)
      ? d.associations.map((a) => (typeof a === 'string' ? { to: norm(a), name: null } : { to: norm(a?.to), name: a?.name ? norm(a.name) : null })).filter((a) => a.to) : null,
  };
}
const tplCustom = Object.entries(T.customObjects || {}).map(([k, v]) => normTemplate(norm(k), v, false));
const tplStd = Object.entries(T.standardObjects || {}).map(([k, v]) => [norm(STD_ALIAS[norm(k)] || k), v]).filter(([k]) => {
  if (STD[k]) return true; templateWarnings.push(`standardObjects.${k}: not a supported standard object, skipped`); return false;
}).map(([k, v]) => normTemplate(k, v, true));

// ── Actual schemas ───────────────────────────────────────────────────────────
const actualCustom = Array.isArray(ctx.actual?.customObjects) ? ctx.actual.customObjects : [];
const byKey = new Map();
for (const s of actualCustom) for (const k of [s.name, s.fullyQualifiedName, s.objectTypeId]) if (k) byKey.set(norm(k), s);
const resolveTarget = (to) => {
  const t = STD_ALIAS[to] || to;
  if (STD[t]) return { id: STD[t], label: STD_LABEL[t] };
  if (/^\d+-\d+$/.test(t)) return { id: t, label: ID_TO_STD[t] ? STD_LABEL[ID_TO_STD[t]] : t };
  const s = byKey.get(t);
  if (s) return { id: s.objectTypeId, label: s.labels?.singular || s.name };
  return { id: null, label: t, missingObject: tplCustom.some((o) => o.key === t) };
};
const labelOfId = (id) => (ID_TO_STD[id] ? STD_LABEL[ID_TO_STD[id]] : (actualCustom.find((s) => s.objectTypeId === id)?.labels?.singular || id));

// ── Findings ─────────────────────────────────────────────────────────────────
const findings = [];
const objects = [];
const unreadable = new Set();
const fmtList = (a, n = 6) => (a.length > n ? `${a.slice(0, n).join(', ')} +${a.length - n} more` : a.join(', '));
function add(obj, rule, property, message, expected, actual, meta = {}) {
  const severity = sevOf(rule);
  if (!severity || severity === 'ignore') return;
  const detail = meta.detail ? `:${meta.detail}` : '';
  const key = `${obj.key}:${rule}${property ? `:${property}` : ''}${detail}`;
  const p = prev[key];
  findings.push({
    key, rule, severity, object: obj.key, objectLabel: obj.label, objectTypeId: obj.objectTypeId || null, fullyQualifiedName: obj.fqn || null, kind: obj.kind,
    property: property || null, message, expected: expected ?? null, actual: actual ?? null,
    changedAt: meta.changedAt || null, changedByUserId: cfg.showChangedBy ? (meta.changedBy || null) : undefined,
    status: p ? 'persisting' : 'new', firstSeenAt: p?.firstSeenAt || new Date(now).toISOString(),
  });
}

function checkProperties(obj, tpl, actualProps) {
  const aProps = new Map(actualProps.map((p) => [norm(p.name), p]));
  const meta = (ap) => ({ changedAt: ap?.updatedAt || null, changedBy: ap?.updatedUserId || null });
  const missing = [];
  for (const [name, ep] of Object.entries(tpl.properties)) {
    const ap = aProps.get(name);
    if (!ap) { missing.push(name); continue; }
    if (ap.archived === true) { add(obj, 'property_archived', name, `\`${name}\` is archived (deleted from the UI)`, 'active', 'archived', meta(ap)); continue; }
    const at = normType(ap.type);
    if (ep.type && at !== ep.type) add(obj, 'property_type_changed', name, `\`${name}\` type changed: ${ep.type} → ${at || 'none'}`, ep.type, at, meta(ap));
    else if (ep.fieldType && norm(ap.fieldType) !== ep.fieldType) add(obj, 'property_field_type_changed', name, `\`${name}\` field type changed: ${ep.fieldType} → ${norm(ap.fieldType) || 'none'}`, ep.fieldType, norm(ap.fieldType), meta(ap));
    if (ep.options) {
      const opts = Array.isArray(ap.options) ? ap.options : [];
      const all = new Map(opts.map((o) => [norm(o.value), o]));
      const removed = ep.options.filter((v) => !all.has(v));
      const hidden = ep.options.filter((v) => all.has(v) && all.get(v).hidden === true);
      const added = [...all.keys()].filter((v) => v && !ep.options.includes(v));
      if (removed.length) add(obj, 'property_option_removed', name, `\`${name}\` option${removed.length > 1 ? 's' : ''} removed: ${fmtList(removed)}`, ep.options, [...all.keys()], { ...meta(ap), detail: removed.sort().join('|') });
      if (hidden.length) add(obj, 'property_option_hidden', name, `\`${name}\` option${hidden.length > 1 ? 's' : ''} hidden: ${fmtList(hidden)}`, null, hidden, { ...meta(ap), detail: hidden.sort().join('|') });
      if (added.length) add(obj, ep.allowExtraOptions ? 'property_option_added' : 'property_option_added_locked', name, `\`${name}\` new option${added.length > 1 ? 's' : ''}: ${fmtList(added)}`, null, added, { ...meta(ap), detail: added.sort().join('|') });
    }
    if (ep.hasUniqueValue !== null && Boolean(ap.hasUniqueValue) !== ep.hasUniqueValue) add(obj, 'property_unique_changed', name, `\`${name}\` unique-value flag changed: ${ep.hasUniqueValue} → ${Boolean(ap.hasUniqueValue)}`, ep.hasUniqueValue, Boolean(ap.hasUniqueValue), meta(ap));
    if (ep.label !== null && String(ap.label ?? '').trim() !== String(ep.label).trim()) add(obj, 'property_label_changed', name, `\`${name}\` label changed: "${ep.label}" → "${ap.label ?? ''}"`, ep.label, ap.label ?? '', meta(ap));
  }
  const total = Object.keys(tpl.properties).length;
  if (missing.length >= 5 && missing.length / Math.max(1, total) >= cfg.massLossRatio) {
    add(obj, 'mass_property_loss', null, `${missing.length} of ${total} managed properties missing (${fmtList(missing)}). Verify the token's portal and scopes before restoring anything.`, total, total - missing.length);
  } else for (const name of missing) add(obj, 'property_missing', name, `\`${name}\` is missing (deleted or renamed)`, 'present', 'missing');
  // unmanaged
  if (tpl.reportUnmanaged) {
    const unmanaged = actualProps.filter((p) => {
      const n = norm(p.name);
      return n && !tpl.properties[n] && p.hubspotDefined !== true && p.archived !== true && !isIgnoredProp(n);
    });
    for (const p of unmanaged) add(obj, tpl.allowUnmanaged ? 'property_unmanaged' : 'property_unmanaged_locked', norm(p.name),
      `\`${norm(p.name)}\` (${normType(p.type)}) is not in the template${tpl.allowUnmanaged ? '' : ' and this object is locked'}`, null, normType(p.type), meta(p));
    if (tpl.allowUnmanaged && unmanaged.length > cfg.unmanagedPropertyWarnCount) add(obj, 'unmanaged_property_volume', null,
      `${unmanaged.length} unmanaged properties (threshold ${cfg.unmanagedPropertyWarnCount})`, cfg.unmanagedPropertyWarnCount, unmanaged.length);
  }
}

// custom objects in template
for (const tpl of tplCustom) {
  const s = byKey.get(tpl.key);
  const obj = { key: tpl.key, label: s?.labels?.singular || tpl.labels?.singular || tpl.key, objectTypeId: s?.objectTypeId, fqn: s?.fullyQualifiedName, kind: 'custom', required: tpl.required };
  const before = findings.length;
  if (!s) { add(obj, 'object_missing', null, `Custom object \`${tpl.key}\` is missing (deleted, archived or not visible to this token)`, 'present', 'missing'); objects.push({ ...obj, state: 'missing', updatedAt: null }); continue; }
  if (s.archived === true) { add(obj, 'object_archived', null, `Custom object \`${tpl.key}\` is archived`, 'active', 'archived', { changedAt: s.updatedAt }); objects.push({ ...obj, state: 'archived', updatedAt: s.updatedAt || null }); continue; }
  if (tpl.labels) for (const k of ['singular', 'plural']) if (tpl.labels[k] !== undefined && String(s.labels?.[k] ?? '').trim() !== String(tpl.labels[k]).trim())
    add(obj, 'object_label_changed', null, `${k} label changed: "${tpl.labels[k]}" → "${s.labels?.[k] ?? ''}"`, tpl.labels[k], s.labels?.[k] ?? '', { detail: k, changedAt: s.updatedAt });
  if (tpl.primaryDisplayProperty && norm(s.primaryDisplayProperty) !== tpl.primaryDisplayProperty)
    add(obj, 'primary_display_changed', null, `primary display property changed: ${tpl.primaryDisplayProperty} → ${norm(s.primaryDisplayProperty) || 'none'}`, tpl.primaryDisplayProperty, norm(s.primaryDisplayProperty), { changedAt: s.updatedAt });
  if (!Array.isArray(s.properties)) {
    add(obj, 'object_not_readable', null, 'Property definitions were not returned for this object. Property checks skipped.', 'properties', 'none');
    unreadable.add(tpl.key);
  } else {
    if (tpl.requiredDeclared) {
      const req = new Set((s.requiredProperties || []).map(norm));
      for (const r of tpl.required) if (!req.has(r)) add(obj, 'required_flag_removed', r, `\`${r}\` is no longer required`, true, false, { changedAt: s.updatedAt });
      for (const r of req) if (!tpl.required.includes(r)) add(obj, 'required_flag_added', r, `\`${r}\` is now required (record creates without it will fail)`, false, true, { changedAt: s.updatedAt });
    }
    checkProperties(obj, tpl, s.properties);
  }
  if (tpl.associations) {
    const assocs = Array.isArray(s.associations) ? s.associations : [];
    const has = (id, name) => assocs.some((a) => ((a.fromObjectTypeId === s.objectTypeId && a.toObjectTypeId === id) || (a.toObjectTypeId === s.objectTypeId && a.fromObjectTypeId === id)) && (!name || norm(a.name) === name));
    const expectedIds = new Set();
    for (const a of tpl.associations) {
      const t = resolveTarget(a.to);
      if (!t.id) { if (t.missingObject) add(obj, 'association_missing', null, `association to \`${a.to}\` missing (target object is missing)`, a.to, 'missing', { detail: a.to }); else templateWarnings.push(`${tpl.key}: association target "${a.to}" is not a known object`); continue; }
      expectedIds.add(t.id);
      if (!has(t.id, a.name)) add(obj, 'association_missing', null, `association to ${t.label}${a.name ? ` (\`${a.name}\`)` : ''} is missing`, a.to, 'missing', { detail: a.to });
    }
    const extra = [...new Set(assocs.map((a) => (a.fromObjectTypeId === s.objectTypeId ? a.toObjectTypeId : a.fromObjectTypeId)))].filter((id) => id && id !== s.objectTypeId && !expectedIds.has(id));
    for (const id of extra) add(obj, 'association_unmanaged', null, `association to ${labelOfId(id)} is not in the template`, null, id, { detail: id });
  }
  objects.push({ ...obj, state: findings.length > before ? 'drift' : 'ok', updatedAt: s.updatedAt || null });
}
// unmanaged custom objects
const managedKeys = new Set(tplCustom.map((o) => o.key));
for (const s of actualCustom) {
  const keys = [s.name, s.fullyQualifiedName, s.objectTypeId].map(norm);
  if (keys.some((k) => managedKeys.has(k)) || s.archived === true || isIgnoredObj(...keys)) continue;
  const obj = { key: norm(s.name), label: s.labels?.singular || s.name, objectTypeId: s.objectTypeId, fqn: s.fullyQualifiedName, kind: 'custom', required: [] };
  const n0 = findings.length;
  add(obj, 'object_unmanaged', null, `Custom object \`${s.fullyQualifiedName || s.name}\` is not in the template (${((k) => `${k} custom propert${k === 1 ? 'y' : 'ies'}`)((s.properties || []).filter((p) => !p.hubspotDefined).length)})`, null, s.objectTypeId, { changedAt: s.createdAt || s.updatedAt });
  if (T.allowUnmanagedObjects === true && findings.length > n0) findings[findings.length - 1].severity = 'info';
  objects.push({ ...obj, state: 'unmanaged', updatedAt: s.updatedAt || null });
}
// standard objects
for (const tpl of tplStd) {
  const a = ctx.actual?.standardObjects?.[tpl.key];
  const obj = { key: tpl.key, label: STD_LABEL[tpl.key], objectTypeId: STD[tpl.key], fqn: tpl.key, kind: 'standard', required: [] };
  const before = findings.length;
  if (!a || !Array.isArray(a.properties)) {
    add(obj, 'object_not_readable', null, `Properties could not be read: ${a?.readError || 'no response'}. Check the crm.schemas.${tpl.key}.read scope.`, 'readable', 'error');
    unreadable.add(tpl.key); objects.push({ ...obj, state: 'unreadable', updatedAt: null }); continue;
  }
  checkProperties(obj, tpl, a.properties);
  objects.push({ ...obj, state: findings.length > before ? 'drift' : 'ok', updatedAt: null });
}

// ── Sort, count, resolve ─────────────────────────────────────────────────────
findings.sort((a, b) => SEV[b.severity] - SEV[a.severity] || a.object.localeCompare(b.object) || String(a.property).localeCompare(String(b.property)));
const keys = new Set(findings.map((f) => f.key));
const resolved = []; const carryOver = [];
for (const [k, v] of Object.entries(prev)) {
  if (keys.has(k)) continue;
  if (unreadable.has(k.split(':')[0])) { carryOver.push(k); continue; }
  resolved.push({ key: k, severity: v.severity, message: v.message || k, firstSeenAt: v.firstSeenAt || null });
}
const min = SEV[cfg.alertMinSeverity] || SEV.warning;
const alertable = findings.filter((f) => SEV[f.severity] >= min);
const counts = {
  critical: findings.filter((f) => f.severity === 'critical').length, warning: findings.filter((f) => f.severity === 'warning').length,
  info: findings.filter((f) => f.severity === 'info').length, total: findings.length, alertable: alertable.length,
  new: findings.filter((f) => f.status === 'new').length, persisting: findings.filter((f) => f.status === 'persisting').length,
  resolved: resolved.length, objectsAudited: objects.length,
};
const status = counts.critical >= cfg.criticalFailThreshold ? 'fail' : (counts.critical + counts.warning > 0 ? 'drift' : 'pass');
const resolvedAlertable = resolved.filter((r) => SEV[r.severity] >= min);

// ── Alert decision ───────────────────────────────────────────────────────────
let alert;
if (!alertable.length && !(cfg.alertOnResolved && resolvedAlertable.length)) alert = { needed: false, reason: findings.length ? 'below_alert_threshold' : 'no_drift' };
else if (!persist || !cfg.suppressRepeatAlerts) alert = { needed: true, reason: 'drift' };
else {
  const fresh = alertable.filter((f) => f.status === 'new').length;
  const lastAlert = Date.parse(mem.lastAlertAt || '') || 0;
  const reminder = alertable.some((f) => f.severity === 'critical') && now - lastAlert >= cfg.reminderHours * 3600000;
  const res = cfg.alertOnResolved && resolvedAlertable.length > 0;
  alert = fresh ? { needed: true, reason: 'new_drift' } : reminder ? { needed: true, reason: 'critical_reminder' } : res ? { needed: true, reason: 'drift_resolved' } : { needed: false, reason: 'repeat_suppressed' };
}
const notes = [];
if (tplCustom.length && !actualCustom.length) notes.push('HubSpot returned no custom objects. Check that the token belongs to the intended portal and has crm.schemas.custom.read.');
if (unreadable.size) notes.push(`Not audited (read errors): ${[...unreadable].join(', ')}. Their previous findings are carried over.`);

// ── Optional template snapshot (bootstrap from the current portal) ───────────
let templateSnapshot;
if (cfg.generateTemplateSnapshot) {
  const snapProps = (props) => Object.fromEntries((props || []).filter((p) => p.hubspotDefined !== true && p.archived !== true && !isIgnoredProp(norm(p.name))).map((p) => {
    const e = { type: normType(p.type), fieldType: norm(p.fieldType), label: p.label };
    if (Array.isArray(p.options) && p.options.length) e.options = p.options.filter((o) => o.hidden !== true).map((o) => o.value);
    if (p.hasUniqueValue) e.hasUniqueValue = true;
    return [norm(p.name), e];
  }));
  templateSnapshot = { templateVersion: `snapshot-${new Date(now).toISOString().slice(0, 10)}`, managedBy: 'Generated by n8n-hubspot-custom-object-schema-drift-detector. Review before use.', customObjects: {}, standardObjects: {} };
  for (const s of actualCustom.filter((x) => x.archived !== true)) templateSnapshot.customObjects[norm(s.name)] = {
    labels: s.labels, primaryDisplayProperty: s.primaryDisplayProperty, requiredProperties: s.requiredProperties || [], properties: snapProps(s.properties),
    associations: [...new Set((s.associations || []).map((a) => (a.fromObjectTypeId === s.objectTypeId ? a.toObjectTypeId : a.fromObjectTypeId)))].filter((id) => id !== s.objectTypeId)
      .map((id) => ({ to: ID_TO_STD[id] || norm(actualCustom.find((x) => x.objectTypeId === id)?.name || id) })),
  };
  for (const tpl of tplStd) { const a = ctx.actual?.standardObjects?.[tpl.key]; if (a && Array.isArray(a.properties)) templateSnapshot.standardObjects[tpl.key] = { properties: snapProps(a.properties) }; }
}

return [{ json: { ...base, status, auditError: null, templateVersion: T.templateVersion || null, templateWarnings, objects, findings, resolved, carryOver, counts, alert, notes, ...(templateSnapshot ? { templateSnapshot } : {}) } }];

// ─────────────────────────────────────────────────────────────────────────────
// Build Governance Report (Slack Block Kit)
// One message per audit: status header, per-object discrepancies (critical
// first), links to HubSpot property settings, resolved items and audit context.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const A = $input.first().json;
const SEV = { info: 1, warning: 2, critical: 3 };
const ICON = { critical: '🔴', warning: '🟠', info: '🔵' };
const min = SEV[cfg.alertMinSeverity] || 2;
const portal = A.portalId || '';
const fill = (t, o) => String(t || '').replace(/\{appHost\}/g, cfg.appHost).replace(/\{portalId\}/g, portal).replace(/\{objectTypeId\}/g, encodeURIComponent(o.objectTypeId || ''));
const settingsUrl = (o) => (portal && o.objectTypeId ? fill(cfg.propertySettingsUrlTemplate, o) : null);
const clip = (t, n) => (t.length > n ? `${t.slice(0, n - 1)}…` : t);
const blocks = [];
const ctxLine = () => `Portal ${portal || 'n/a'} · template ${A.templateVersion || 'unversioned'} (${A.templateSource}) · run ${cfg.runId}`;

if (A.status === 'error') {
  blocks.push({ type: 'header', text: { type: 'plain_text', text: '⚠️ HubSpot schema audit could not run', emoji: true } });
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: clip(`*${A.auditError.kind === 'template' ? 'Expected template problem' : 'HubSpot read failed'}*\n${A.auditError.messages.map((m) => `• ${m}`).join('\n')}\n\nNo drift checks ran, so this is not an all-clear.`, 2900) } });
  blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: ctxLine() }] });
} else {
  const c = A.counts;
  const head = { fail: '🔴 Schema drift: FAIL', drift: '🟠 Schema drift detected', pass: '🟢 Schema matches template' }[A.status];
  blocks.push({ type: 'header', text: { type: 'plain_text', text: clip(`${head} · ${c.critical} critical · ${c.warning} warning · ${c.info} info`, 150), emoji: true } });
  const why = { new_drift: `${A.findings.filter((f) => f.status === 'new' && SEV[f.severity] >= min).length} new since the last audit`, critical_reminder: `reminder: critical drift still open (every ${cfg.reminderHours}h)`, drift_resolved: 'drift resolved since the last audit', drift: 'audit result' }[A.alert.reason] || '';
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `*${c.objectsAudited} objects audited* against the expected template${why ? ` · _${why}_` : ''}.${A.notes.length ? `\n${A.notes.map((n) => `⚠️ ${n}`).join('\n')}` : ''}` } });
  const shown = A.findings.filter((f) => SEV[f.severity] >= min || (cfg.includeInfoInSlack && f.severity === 'info'));
  const hiddenInfo = A.findings.length - shown.length;
  const groups = [];
  for (const f of shown) { let g = groups.find((x) => x.object === f.object); if (!g) { g = { object: f.object, o: f, items: [] }; groups.push(g); } g.items.push(f); }
  const n = (g, sv) => g.items.filter((f) => f.severity === sv).length;
  groups.sort((a, b) => n(b, 'critical') - n(a, 'critical') || n(b, 'warning') - n(a, 'warning') || b.items.length - a.items.length);
  const maxGroups = 12;
  for (const g of groups.slice(0, maxGroups)) {
    const o = g.o; const st = A.objects.find((x) => x.key === g.object);
    const title = `*${o.objectLabel}* ${o.kind === 'custom' ? `(\`${o.fullyQualifiedName || o.object}\`${o.objectTypeId ? `, ${o.objectTypeId}` : ''})` : '(standard object)'}`;
    const lines = g.items.slice(0, cfg.maxLinesPerObject).map((f) => `${ICON[f.severity]} ${f.message}${f.status === 'new' && A.persist ? ' · *new*' : ''}${f.changedByUserId ? ` · user ${f.changedByUserId}` : ''}`);
    if (g.items.length > cfg.maxLinesPerObject) lines.push(`_+${g.items.length - cfg.maxLinesPerObject} more in the audit log_`);
    const mod = st?.updatedAt ? `\n_Schema last modified ${st.updatedAt.slice(0, 16).replace('T', ' ')} UTC_` : '';
    const sec = { type: 'section', text: { type: 'mrkdwn', text: clip(`${title}\n${lines.join('\n')}${mod}`, 2900) } };
    const u = settingsUrl(o);
    if (u) sec.accessory = { type: 'button', text: { type: 'plain_text', text: 'Property settings' }, url: u };
    blocks.push({ type: 'divider' }, sec);
  }
  if (groups.length > maxGroups) blocks.push({ type: 'section', text: { type: 'mrkdwn', text: `_+${groups.length - maxGroups} more objects with drift in the audit log._` } });
  if (!shown.length && A.status === 'pass') blocks.push({ type: 'section', text: { type: 'mrkdwn', text: '✅ No discrepancies at or above the alert threshold.' } });
  if (A.resolved.length && cfg.alertOnResolved) blocks.push({ type: 'divider' }, { type: 'section', text: { type: 'mrkdwn', text: clip(`✅ *Resolved since the last audit (${A.resolved.length})*\n${A.resolved.slice(0, 8).map((r) => `• ${r.message}`).join('\n')}${A.resolved.length > 8 ? `\n_+${A.resolved.length - 8} more_` : ''}`, 2900) } });
  if (cfg.dataModelUrl) blocks.push({ type: 'actions', elements: [{ type: 'button', text: { type: 'plain_text', text: 'Data model overview' }, url: cfg.dataModelUrl }] });
  blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `${ctxLine()}${hiddenInfo ? ` · ${hiddenInfo} lower-severity findings in the audit log` : ''}` }] });
}
const text = A.status === 'error' ? 'HubSpot schema audit could not run' : `HubSpot schema drift: ${A.counts.critical} critical, ${A.counts.warning} warning, ${A.counts.info} info`;
return [{ json: { message: { text, blocks: blocks.slice(0, 49) }, alertNeeded: A.alert.needed, slackAllowed: cfg.sendSlackAlerts && A.alert.needed } }];

// Collect Slack Results: Slack incoming webhooks answer "ok" (text) on success.
const r = $input.first().json;
const ok = !r.error && (r.data === undefined || String(r.data).trim() === 'ok' || r.ok === true);
return [{ json: { sent: ok ? 1 : 0, failed: ok ? 0 : 1, error: ok ? null : String(r.error?.message || r.error || r.data || 'unknown').slice(0, 200) } }];

// ─────────────────────────────────────────────────────────────────────────────
// Build Run Summary & Record State
// JSON for ALERT_WEBHOOK_URL (GRC tooling, BI, ticketing) plus workflow memory.
// Memory is written only for production executions, and only when the alert
// was delivered or not needed, so an undelivered finding stays "new".
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const A = $('Schema Drift Analysis').first().json;
let sl = null; try { sl = $('Collect Slack Results').isExecuted ? $('Collect Slack Results').first().json : null; } catch (e) { sl = null; }
const delivered = Boolean(sl && sl.sent > 0);
const body = {
  event: 'hubspot.schema_drift.audit', runId: cfg.runId, generatedAt: A.generatedAt, portalId: A.portalId || null,
  mode: cfg.sandboxMode ? 'sandbox' : cfg.dryRun ? 'dry_run' : 'live', status: A.status, auditError: A.auditError,
  templateVersion: A.templateVersion, templateSource: A.templateSource, counts: A.counts, alertReason: A.alert.reason,
  findings: A.findings.map((f) => ({ key: f.key, rule: f.rule, severity: f.severity, object: f.object, objectTypeId: f.objectTypeId, property: f.property, expected: f.expected, actual: f.actual, status: f.status, firstSeenAt: f.firstSeenAt })),
  resolved: A.resolved.map((r) => ({ key: r.key, severity: r.severity })), slack: sl ? { sent: sl.sent, failed: sl.failed } : null,
};
let recorded = false;
if (A.persist && A.status !== 'error' && (!A.alert.needed || delivered)) {
  const store = $getWorkflowStaticData('global');
  const prev = store.schemaDrift?.findings || {};
  const findings = {};
  for (const k of A.carryOver || []) if (prev[k]) findings[k] = prev[k];
  for (const f of A.findings) findings[f.key] = { severity: f.severity, message: f.message, firstSeenAt: f.firstSeenAt, lastSeenAt: A.generatedAt };
  store.schemaDrift = { findings, lastAuditAt: A.generatedAt, lastAlertAt: delivered ? A.generatedAt : (store.schemaDrift?.lastAlertAt || null), lastStatus: A.status };
  recorded = true;
}
const sendAllowed = cfg.webhookEnabled && (A.alert.needed || cfg.notifyOnEveryRun);
return [{ json: { body, sendAllowed, recorded, delivered } }];

// ─────────────────────────────────────────────────────────────────────────────
// Execution Summary & Audit
// Final record on every path: outcome, safety flags, counts, every finding
// (schema metadata only, no record data), delivery results.
// ─────────────────────────────────────────────────────────────────────────────
const cfg = $('Config & Safety Gate').first().json.config;
const A = $('Schema Drift Analysis').first().json;
const S = $('Build Run Summary').first().json;
const B = $('Build Governance Report').first().json;
let sl = null; try { sl = $('Collect Slack Results').isExecuted ? $('Collect Slack Results').first().json : null; } catch (e) { sl = null; }
let wh = 'not_sent';
try { if ($('Webhook: Post Run Summary').isExecuted) { const r = $('Webhook: Post Run Summary').first().json; wh = r.error ? `failed: ${String(r.error.message || r.error).slice(0, 120)}` : 'sent'; } } catch (e) { wh = 'not_sent'; }
let outcome;
if (A.status === 'error') outcome = sl?.sent ? 'audit_failed_alerted' : `audit_failed_${A.auditError.kind}`;
else if (!A.alert.needed) outcome = { no_drift: 'no_drift', below_alert_threshold: 'drift_below_alert_threshold', repeat_suppressed: 'drift_alert_suppressed' }[A.alert.reason] || 'no_alert';
else if (cfg.sandboxMode) outcome = 'drift_found_sandbox';
else if (cfg.dryRun) outcome = 'drift_found_dry_run';
else if (!cfg.sendSlackAlerts) outcome = 'drift_found_alerts_disabled';
else outcome = sl?.sent ? 'drift_alerted' : 'drift_alert_failed';
return [{ json: {
  workflow: 'n8n-hubspot-custom-object-schema-drift-detector', runId: cfg.runId, executionMode: cfg.executionMode, finishedAt: new Date().toISOString(), outcome,
  safety: { sandboxMode: cfg.sandboxMode, dryRun: cfg.dryRun, sendSlackAlerts: cfg.sendSlackAlerts, webhookEnabled: cfg.webhookEnabled, hubspotWrites: 'none (read-only workflow)' },
  thresholds: { alertMinSeverity: cfg.alertMinSeverity, criticalFailThreshold: cfg.criticalFailThreshold, unmanagedPropertyWarnCount: cfg.unmanagedPropertyWarnCount, massLossRatio: cfg.massLossRatio, reminderHours: cfg.reminderHours },
  status: A.status, auditError: A.auditError, templateVersion: A.templateVersion, templateSource: A.templateSource, templateWarnings: A.templateWarnings,
  counts: A.counts, alert: A.alert, notes: A.notes,
  objects: A.objects.map((o) => ({ object: o.key, kind: o.kind, objectTypeId: o.objectTypeId || null, state: o.state, findings: A.findings.filter((f) => f.object === o.key).length })),
  findings: A.findings.map((f) => ({ severity: f.severity, rule: f.rule, object: f.object, property: f.property, message: f.message, expected: f.expected, actual: f.actual, status: f.status, changedAt: f.changedAt })),
  resolved: A.resolved, slack: sl ? { sent: sl.sent, failed: sl.failed, error: sl.error } : { sent: 0, failed: 0, built: B.alertNeeded },
  runSummaryWebhook: wh, stateRecorded: S.recorded,
  ...(A.templateSnapshot ? { templateSnapshot: A.templateSnapshot } : {}),
} }];
